(10, 0, 3, 'ship-stats', '[\n                                          {\n                                            \"ShipType\": \"Barge\",\n                                            \"Health\": 2800,\n                                            \"Range\": [80],\n                                            \"Power\": [300],\n                                            \"RateOfFire\": [0],\n                                            \"RotationRates\": [0],\n                                            \"Speed\": 2,\n                                            \"Sight\": 40,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [.5],\n                                            \"WeaponTypes\": [\"Bomb\"],\n                                            \"Description\": \"Very large, slow, heavily armored ship with no weapons and slow movement. Can protect other ships behind it.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Carrier\",\n                                            \"Health\": 1300,\n                                            \"Range\": [],\n                                            \"Power\": [],\n                                            \"RateOfFire\": [],\n                                            \"RotationRates\": [],\n                                            \"Speed\": 4,\n                                            \"Sight\": 40,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [],\n                                            \"WeaponTypes\": [],\n                                            \"Description\": \"Large, slow, heavily armored ship, that carries a number of drones and strikers but possesses no weapons of its own.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Cruiser\",\n                                            \"Health\": 400,\n                                            \"Range\": [120],\n                                            \"Power\": [150],\n                                            \"RateOfFire\": [2],\n                                            \"RotationRates\": [180],\n                                            \"Speed\": 6,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [1.75],\n                                            \"WeaponTypes\": [\"Beam Cannon\"],\n                                            \"Description\": \"Slow, medium sized, lightly armored ship that fires powerful, long range laser beams.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Dreadnought\",\n                                            \"Health\": 550,\n                                            \"Range\": [80],\n                                            \"Power\": [125],\n                                            \"RateOfFire\": [2],\n                                            \"RotationRates\": [120],\n                                            \"Speed\": 7.5,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [1],\n                                            \"WeaponTypes\": [\"Light Cannon\"], // type of turret\n                                            \"Description\": \"The more common workhorse of the fleet. Medium ship, medium speed, medium range, powerful weapons.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Drone\",\n                                            \"Health\": 40,\n                                            \"Range\": [40],\n                                            \"Power\": [15],\n                                            \"RateOfFire\": [2],\n                                            \"RotationRates\": [306],\n                                            \"Speed\": 25.5,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [1],\n                                            \"WeaponTypes\": [\"Turret\"],\n                                            \"Description\": \"Very small, very fast, unmanned, low powered ship that must be carried by a carrier. Good for swarming enemies\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Factory\",\n                                            \"Health\": 850,\n                                            \"Range\": [],\n                                            \"Power\": [],\n                                            \"RateOfFire\": [],\n                                            \"RotationRates\": [],\n                                            \"Speed\": 4,\n                                            \"Sight\": 40,\n                                            \"AdditionalTsv\": 20000,\n                                            \"ProjectileValue\": [],\n                                            \"WeaponTypes\": [],\n                                            \"Description\": \"Very large, slow, and heavily armored ship. Mines materials and produces ships for the fleet in between levels.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Fire Ship\",\n                                            \"Health\": 1800,\n                                            \"Range\": [0],\n                                            \"Power\": [1500],\n                                            \"RateOfFire\": [0],\n                                            \"RotationRates\": [0],\n                                            \"Speed\": 5,\n                                            \"Sight\": 40,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [2],\n                                            \"WeaponTypes\": [\"Bomb\"],\n                                            \"Description\": \"Large, unmanned barges with no guns but loaded with nuclear bombs. Can be sent towards enemy ships and manually detonated. Can damage friendly ships that are too close to the blast zone.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Flagship\",\n                                            \"Health\": 1500,\n                                            \"Range\": [30, 30, 180],\n                                            \"Power\": [45, 45, 350],\n                                            \"RateOfFire\": [1, 1, 3],\n                                            \"RotationRates\": [200, 200, 100],\n                                            \"Speed\": 4,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [1, 1, 1.75],\n                                            \"WeaponTypes\": [\"Turret\", \"Turret\", \"Full Ship Turret\"],\n                                            \"Description\": \"The capital ship of the fleet, possesses strong armor, an incredibly powerful long range cannon, and close range defenses.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Frigate\",\n                                            \"Health\": 375,\n                                            \"Range\": [40, 40],\n                                            \"Power\": [80, 80],\n                                            \"RateOfFire\": [2, 2],\n                                            \"RotationRates\": [120, 120],\n                                            \"Speed\": 12,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [2, 2],\n                                            \"WeaponTypes\": [\"Turret\", \"Turret\"],\n                                            \"Description\": \"Medium sized ship that moves quickly and fires powerful short range rockets that explode on impact, potentially damaging multiple targets.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Gunship\",\n                                            \"Health\": 300,\n                                            \"Range\": [40],\n                                            \"Power\": [60],\n                                            \"RateOfFire\": [2.5],\n                                            \"RotationRates\": [200],\n                                            \"Speed\": 15.75,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [1],\n                                            \"WeaponTypes\": [\"Dual Cannon\"],\n                                            \"Description\": \"Small and fast, fires short range dual laser cannons.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Scout\",\n                                            \"Health\": 50,\n                                            \"Range\": [],\n                                            \"Power\": [],\n                                            \"RateOfFire\": [],\n                                            \"RotationRates\": [],\n                                            \"Speed\": 21,\n                                            \"Sight\": 80,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [],\n                                            \"WeaponTypes\": [],\n                                            \"Description\": \"Small, very fast ship that can \\\"see\\\" in a large range around it and clear the fog of war.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Striker\",\n                                            \"Health\": 300,\n                                            \"Range\": [0],\n                                            \"Power\": [150],\n                                            \"RateOfFire\": [0],\n                                            \"RotationRates\": [0],\n                                            \"Speed\": 18.75,\n                                            \"Sight\": 40,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [1],\n                                            \"WeaponTypes\": [\"Bomb\"],\n                                            \"Description\": \"Very small and fast but vulnerable during bombing run. Carries a payload of bombs to a single target and does a lot of damage. Returns to carrier to reload. Must be carried by a carrier.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Warp Gate\",\n                                            \"Health\": 1350,\n                                            \"Range\": [],\n                                            \"Power\": [],\n                                            \"RateOfFire\": [],\n                                            \"RotationRates\": [],\n                                            \"Speed\": 2,\n                                            \"Sight\": 40,\n                                            \"AdditionalTsv\": 45000,\n                                            \"ProjectileValue\": [],\n                                            \"WeaponTypes\": [],\n                                            \"Description\": \"Slow, unmanned, heavily armored ship that allows other ships to retreat from the current level or call in limited reinforcements. If destroyed, the remaining ships must win or die. The Warp Gate cannot warp itself and will be lost any time a retreat is made.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Beehive\",\n                                            \"Health\": 1200,\n                                            \"Range\": [],\n                                            \"Power\": [],\n                                            \"RateOfFire\": [],\n                                            \"RotationRates\": [],\n                                            \"Speed\": 2,\n                                            \"Sight\": 40,\n                                            \"AdditionalTsv\": 250000,\n                                            \"ProjectileValue\": [],\n                                            \"WeaponTypes\": [],\n                                            \"Description\": \"A large, armored data center. The Beehive ships do not fight but they store information that the Bees have gathered about their opponent. Whenever the player destroys Beehives, some of the actual data that the Hive Mind has on the player is removed, hindering the Bees ability to strategize.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Bumblebee\",\n                                            \"Health\": 900,\n                                            \"Range\": [160],\n                                            \"Power\": [200],\n                                            \"RateOfFire\": [2.75],\n                                            \"RotationRates\": [180],\n                                            \"Speed\": 7,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [1.5],\n                                            \"WeaponTypes\": [\"Turret\"],\n                                            \"Description\": \"The heavy muscle of the Bees. A large ship that moves at medium speed, posession heavy armor and powerful, long range weapons that can dominate the battlefied.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Carpenter Bee\",\n                                            \"Health\": 600,\n                                            \"Range\": [],\n                                            \"Power\": [],\n                                            \"RateOfFire\": [],\n                                            \"RotationRates\": [],\n                                            \"Speed\": 2,\n                                            \"Sight\": 40,\n                                            \"AdditionalTsv\": 15000,\n                                            \"ProjectileValue\": [],\n                                            \"WeaponTypes\": [],\n                                            \"Description\": \"A factory ship. Very slow moving and posessing no defenses. Builds other Bees for the fleet. It doesn\'t actually build ships during battle but the existence of the Carpenter Bees in the fleet increases the number of ships over time until they are destroyed.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Honeybee\",\n                                            \"Health\": 40,\n                                            \"Range\": [],\n                                            \"Power\": [],\n                                            \"RateOfFire\": [],\n                                            \"RotationRates\": [],\n                                            \"Speed\": 22.5,\n                                            \"Sight\": 100,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [],\n                                            \"WeaponTypes\": [],\n                                            \"Description\": \"Small, defenseless, very fast bee that scouts out locations for other bees.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Hornet\",\n                                            \"Health\": 100,\n                                            \"Range\": [40],\n                                            \"Power\": [20],\n                                            \"RateOfFire\": [2],\n                                            \"RotationRates\": [288],\n                                            \"Speed\": 18,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [1],\n                                            \"WeaponTypes\": [\"Eye\"],\n                                            \"Description\": \"Small, fast, packs a small punch but swarms the targets in large numbers until they\'re destroyed.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Leafcutter\",\n                                            \"Health\": 600,\n                                            \"Range\": [80],\n                                            \"Power\": [60],\n                                            \"RateOfFire\": [2], // This is tied to the animation (6 FPS) for the Leafcutter so it shouldn\'t be changed without very good reason\n                                            \"RotationRates\": [250],\n                                            \"Speed\": 10.5,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\":0,\n                                            \"ProjectileValue\": [1.5],\n                                            \"WeaponTypes\": [\"Split Shot\"],\n                                            \"Description\": \"Medium, midrange ship, a sort of light cruiser that stands between the Bumblebees and the Wasps. Fires lasers that split into multiple shots upon hitting their first target, potentially damaging many close targets.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Queen\",\n                                            \"Health\": 7000,\n                                            \"Range\": [140, 70, 70, 70, 70],\n                                            \"Power\": [180, 30, 30, 30, 30],\n                                            \"RateOfFire\": [1.5, .5, .5, .5, .5],\n                                            \"RotationRates\": [125, 250, 250, 250, 250],\n                                            \"Speed\": 4,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\": 3040, // the TSV for 16 Yellow Jackets (190)\n                                            \"ProjectileValue\": [1, 1, 1, 1, 1],\n                                            \"WeaponTypes\": [\"Eye\", \"Eye\", \"Eye\", \"Eye\", \"Eye\"],\n                                            \"Description\": \"The mothership. Massive, heavily armored ship with extensive medium and close range defenses. Builds swarms of Yellow Jackets.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Wasp\",\n                                            \"Health\": 400,\n                                            \"Range\": [40],\n                                            \"Power\": [80],\n                                            \"RateOfFire\": [2.5],\n                                            \"RotationRates\": [240],\n                                            \"Speed\": 15,\n                                            \"Sight\": 0,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [1],\n                                            \"WeaponTypes\": [\"Eye\"],\n                                            \"Description\": \"Small, quick, powerful, and decently armored. These are the tanks of the fleet. Not as strong, or protected as the Bumblebees but there are more of them and they\'re faster. They fire at short range.\"\n                                            \n                                          },\n                                          {\n                                            \"ShipType\": \"Yellow Jacket\",\n                                            \"Health\": 200,\n                                            \"Range\": [0],\n                                            \"Power\": [200],\n                                            \"RateOfFire\": [0],\n                                            \"RotationRates\": [0],\n                                            \"Speed\": 19.5,\n                                            \"Sight\": 40,\n                                            \"AdditionalTsv\": 0,\n                                            \"ProjectileValue\": [1],\n                                            \"WeaponTypes\": [\"Bomb\"],\n                                            \"Description\": \"Suicide bomber bee. Small and very fast, it flies straight towards targets and explodes.\"\n                                            \n                                          }\n                                        ]', '2023-04-29 18:38:14', '2024-04-07 20:46:44');
INSERT INTO `settings` (`Id`, `userId`, `version`, `name`, `contents`, `created_date`, `edited_date`) VALUES
(11, 0, 6, 'ship-stats', '[\r\n {\r\n \"ShipType\": \"Barge\",\r\n \"Health\": 2800,\r\n \"Range\": [80],\r\n \"Power\": [300],\r\n \"RateOfFire\": [0],\r\n \"RotationRates\": [0],\r\n \"Speed\": 3.5,\r\n \"Sight\": 40,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [.5],\r\n \"WeaponTypes\": [\"Bomb\"],\r\n \"Description\": \"The Barge has exceptional defensive capabilities at the cost of its maneuverability and weapons systems. As such, it is best suited for the frontlines, where it can take hits for the fleet’s more fragile ships.\",\r\n \"CodexDescription\": \"The Barge has exceptional defensive capabilities at the cost of its maneuverability and weapons systems. As such, it is best suited for the frontlines, where it can take hits for the fleet’s more fragile ships.\r\n \r\n Strategy\r\n This ship is slow due to its size, so take the time to position it before sending your faster ships in. Protecting your other ships is a priority, and Barges are the best choice for that. \r\n \r\n Lore\r\n Colloquially referred to as \\\"Bricks\\\" by Fleet personnel. Warnings have been issued to restrain the nickname to the ship itself.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Beacon\",\r\n \"Health\": 25,\r\n \"Range\": [],\r\n \"Power\": [],\r\n \"RateOfFire\": [],\r\n \"RotationRates\": [],\r\n \"Speed\": 0,\r\n \"Sight\": 60,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [],\r\n \"WeaponTypes\": [],\r\n \"Description\": \"Beacons are small radars that let you track enemy movements within their range. They are deployed by Scouts and cannot move on their own.\",\r\n \"CodexDescription\": \"Beacons are small radars that let you track enemy movements within their range. They are deployed by Scouts and cannot move on their own.\r\n \r\n Strategy\r\n You can place these in more dangerous areas where you can’t put your own ships to anticipate enemy movements. Additionally, beacons can cover your blind spots to curtail surprise attacks.\r\n \r\n Lore\r\n Scout pilots have bizarrely taken to naming their beacons. Even more bizarre is that the granted names are typically just four seemingly random letters and numbers separated by a dash in the center.\r\n \"\r\n },\r\n {\r\n \"ShipType\": \"Carrier\",\r\n \"Health\": 1300,\r\n \"Range\": [],\r\n \"Power\": [],\r\n \"RateOfFire\": [],\r\n \"RotationRates\": [],\r\n \"Speed\": 4,\r\n \"Sight\": 40,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [],\r\n \"WeaponTypes\": [],\r\n \"Description\": \"Despite carrying no weapons of its own, the Carrier is invaluable as the only way to bring Drones and Strikers into battle, as the fuel capacity for those ships is limited.\",\r\n \"CodexDescription\": \"Despite carrying no weapons of its own, the Carrier is invaluable as the only way to bring Drones and Strikers into battle, as the fuel capacity for those ships is limited.\r\n \r\n Strategy\r\n Carriers have their own production lines for Drones and Strikers, so prioritize keeping them in safety. Drones and Strikers are replaceable, but the Carriers are not.\r\n \r\n Lore\r\n The best engineers on the planet successfully fitted Carriers with full assembly lines for Drones and Strikers. These implement the latest in warp gate technology to supply raw materials. Said engineers apparently couldn’t find a way to include weapons systems.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Cruiser\",\r\n \"Health\": 400,\r\n \"Range\": [120],\r\n \"Power\": [150],\r\n \"RateOfFire\": [2],\r\n \"RotationRates\": [180],\r\n \"Speed\": 6,\r\n \"Sight\": 0,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1.75],\r\n \"WeaponTypes\": [\"Beam Cannon\"],\r\n \"Description\": \"Using the latest in laser technology, cruisers are designed to have the most offensive power at range of the fleet.\",\r\n \"CodexDescription\": \"Using the latest in laser technology, cruisers are designed to have the most offensive power at range of the fleet.\r\n \r\n Strategy\r\n Cruisers provide exceptional firepower at good range, but lack the speed or armor to keep themselves safe. They will perform their best if positioned at their maximum range or behind defensive ships like the Barge.\r\n \r\n Lore\r\n The windshield was redesigned to be tinted after multiple reports of temporary blindness and long-term eye damage after laser usage.\r\n \"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Dreadnought\",\r\n \"Health\": 550,\r\n \"Range\": [80],\r\n \"Power\": [125],\r\n \"RateOfFire\": [2],\r\n \"RotationRates\": [120],\r\n \"Speed\": 9,\r\n \"Sight\": 0,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1],\r\n \"WeaponTypes\": [\"Light Cannon\"], // type of turret\r\n \"Description\": \"The Dreadnought is the most average ship of the fleet, making it a great all-around tool for any situation. Making the most of its versatility is vital to the fleet’s success.\",\r\n \"CodexDescription\": \"The Dreadnought is the most average ship of the fleet, making it a great all-around tool for any situation. Making the most of its versatility is vital to the fleet’s success.\r\n \r\n Strategy\r\n Dreadnoughts make for strong frontline ships, as they are the most durable unit with weapons systems (save for the Flagship). They provide flexibility and stability for your squads, but they need higher firepower ships to back them up or they will eventually be taken down.\r\n \r\n Lore\r\n Dreadnought pilots and crew are among the least respected in the fleet, although not at all to do with their combat performance. Other fleet members just consider them \\\"boring.\\\"\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Drone\",\r\n \"Health\": 40,\r\n \"Range\": [40],\r\n \"Power\": [15],\r\n \"RateOfFire\": [2],\r\n \"RotationRates\": [306],\r\n \"Speed\": 25.5,\r\n \"Sight\": 0,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1],\r\n \"WeaponTypes\": [\"Turret\"],\r\n \"Description\": \"Drones are extremely fast and small, due in no small part to being unmanned ships. They are highly effective at swarming slower targets. Can only be escorted into battles by a Carrier.\",\r\n \"CodexDescription\": \"Drones are extremely fast and small, due in no small part to being unmanned ships. They are highly effective at swarming slower targets. Can only be escorted into battles by a Carrier.\r\n \r\n Strategy\r\n Drones make up for lack of firepower with their speed and ease of production. Use a large grouping of them to swarm slower enemies that only shoot one target at a time.\r\n \r\n Lore\r\n The low material cost and lack of need for pilots make the drone very popular with fleet accountants. Many environmentalists started protesting use of the design, however, after a large grouping of destroyed Drones were spotted in orbit around Uranus. Said environmentalists are being ignored.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Factory\",\r\n \"Health\": 850,\r\n \"Range\": [],\r\n \"Power\": [],\r\n \"RateOfFire\": [],\r\n \"RotationRates\": [],\r\n \"Speed\": 4,\r\n \"Sight\": 40,\r\n \"AdditionalTsv\": 20000,\r\n \"ProjectileValue\": [],\r\n \"WeaponTypes\": [],\r\n \"Description\": \"The Factory ship is a recent advancement in mobile resource gathering. It has no defenses of its own, but it provides invaluable raw materials for ship construction.\r\n \",\r\n \"CodexDescription\": \"The Factory ship is a recent advancement in mobile resource gathering. It has no defenses of its own, but it provides invaluable raw materials for ship construction.\r\n \r\n Strategy\r\n Only bring factory ships when you have determined some amount of raw resources on the battlefield ahead. When you do deploy these ships, make sure they’re heavily guarded, as losing them at any point will lose all the resources they’ve collected.\r\n \r\n Lore\r\n The factory ship isn’t a military invention, but an industrial one. It has been a popular model in the outer reaches, however, as its mobility allows for harvesting materials from asteroids. There have been many fewer deaths by mining accidents since its inception as well! Jensen Industries requested we omit the significant layoffs in the mining industry since the factory ship’s inception.\r\n \"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Fire Ship\",\r\n \"Health\": 1800,\r\n \"Range\": [0],\r\n \"Power\": [2000],\r\n \"RateOfFire\": [0],\r\n \"RotationRates\": [0],\r\n \"Speed\": 5,\r\n \"Sight\": 60,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1.5],\r\n \"WeaponTypes\": [\"Bomb\"],\r\n \"Description\": \"The Fire Barge is an alteration on the Barge’s design, trading its stellar defenses for speed and frightening, single use offense. With a nuclear payload on board, it makes a great last resort against high value targets or large swarms of enemies. Take care that our other units don’t get caught in the blast.\",\r\n \"CodexDescription\": \"The Fire Barge is an alteration on the Barge’s design, trading its stellar defenses for speed and frightening, single use offense. With a nuclear payload on board, it makes a great last resort against high value targets or large swarms of enemies. Take care that our other units don’t get caught in the blast.\r\n \r\n Strategy\r\n Fire Barge explosions have a wide radius and obliterate anything in their path. This means a well placed Fire Barge can cripple the enemy fleet, and a poorly placed one can cripple ours.\r\n \r\n Lore\r\n When an AI was tasked with the most efficient method to eliminate enemy fleets, it provided a similar design to the Fire Barge. It was initially denied due to high material cost and endangerment of human forces. The AI, however, redesigned it to use decommissioned Barges and be piloted entirely by itself. Despite continued reluctance from high command to use the design, the AI became obsessively devoted to piloting itself to death for the fleet, and high command relented.\r\n \\\"The AI pilot seems extremely disappointed every time they successfully detonate a Fire Barge, only to subsequently realize they themselves did not die with the ship. I worry about what we\'ve created.\\\" - Natalia Friedman, Fleet AI Technician.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Flagship\",\r\n \"Health\": 1500,\r\n \"Range\": [30, 30, 180],\r\n \"Power\": [75, 75, 350],\r\n \"RateOfFire\": [1, 1, 3],\r\n \"RotationRates\": [200, 200, 100],\r\n \"Speed\": 4,\r\n \"Sight\": 0,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1, 1, 1.75],\r\n \"WeaponTypes\": [\"Turret\", \"Turret\", \"Full Ship Turret\"],\r\n \"Description\": \"The Flagship is the center of the fleet, and as such, it is appropriately powerful. Boasting state-of-the-art armor and weapons systems, this ship excels at everything but speed.\",\r\n \"CodexDescription\": \"The Flagship is the center of the fleet, and as such, it is appropriately powerful. Boasting state-of-the-art armor and weapons systems, this ship excels at everything but speed.\r\n \r\n Strategy\r\n The Flagship is our most individually powerful ship and the center of command during battles. Its laser cannons incapacitate larger ships effectively and outright destroy smaller ones, but it can easily be swarmed and taken out by a high volume of enemy ships.\r\n \r\n Lore\r\n The Flagship is by far the best equipped ship in the Fleet, sporting all the latest advancements in weapons, engines, and defense systems. Fleet personnel all aim to be promoted to a Flagship someday, although many claim it’s due to the on-board cafeteria more than anything else.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Frigate\",\r\n \"Health\": 375,\r\n \"Range\": [40, 40],\r\n \"Power\": [80, 80],\r\n \"RateOfFire\": [2, 2],\r\n \"RotationRates\": [120, 120],\r\n \"Speed\": 12,\r\n \"Sight\": 0,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [2, 2],\r\n \"WeaponTypes\": [\"Rocket Turret\", \"Rocket Turret\"],\r\n \"Description\": \"Frigates are the explosives experts of the fleet, equipped with short range rockets that can deal crippling damage to a group of targets.\",\r\n \"CodexDescription\": \"Frigates are the explosives experts of the fleet, equipped with short range rockets that can deal crippling damage to a group of targets.\r\n \r\n Strategy\r\n Frigates are at their best against groups of enemy ships, but smaller ships often outspeed them. Be patient when positioning your frigates against these groupings and you will be rewarded.\r\n \r\n Lore\r\n Frigate pilots notably went on strike after the introduction of Strikers to the Fleet arsenal in 2987, preemptively wanting to avoid replacement by AI. An agreement was signed wherein Strikers would only be allowed to carry \\\"worse\\\" bombs. While the pilots union was proud of this success, it should be noted that Strikers were never designed to carry any bigger or better bombs.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Gunship\",\r\n \"Health\": 300,\r\n \"Range\": [40],\r\n \"Power\": [60],\r\n \"RateOfFire\": [2.5],\r\n \"RotationRates\": [200],\r\n \"Speed\": 18.75,\r\n \"Sight\": 0,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1],\r\n \"WeaponTypes\": [\"Dual Cannon\"],\r\n \"Description\": \"Engineered to be quick and highly effective at taking out singular targets, gunships are the fleet’s premier dogfighters.\",\r\n \"CodexDescription\": \"Engineered to be quick and highly effective at taking out singular targets, gunships are the fleet’s premier dogfighters. \r\n \r\n Strategy\r\n Gunships are designed for single combat, or as close to single combat as spaceship fleets can manage. This makes them a strong option for hunting down isolated enemies, but they cannot survive long if too many enemies take notice.\r\n \r\n Lore\r\n Gunship pilots are the most reprimanded subset of Fleet personnel, with the most common infraction being usage of sunglasses not approved for dress code in the Fleet Handbook (Article 14, Subsection E).\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Scout\",\r\n \"Health\": 50,\r\n \"Range\": [],\r\n \"Power\": [],\r\n \"RateOfFire\": [],\r\n \"RotationRates\": [],\r\n \"Speed\": 21,\r\n \"Sight\": 80,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [],\r\n \"WeaponTypes\": [],\r\n \"Description\": \"Scouts are frail, non combat units given the specific purpose to provide information on the battlefield. As such, they are the fastest independent ship in the fleet and have the most advanced radars, giving them unparalleled vision over enemy movements.\",\r\n \"CodexDescription\": \"Scouts are frail, non combat units given the specific purpose to provide information on the battlefield. As such, they are the fastest independent ship in the fleet and have the most advanced radars, giving them unparalleled vision over enemy movements.\r\n \r\n Strategy\r\n Information is power, and Scouts provide just that. As long as they stay moving, it will be difficult for enemy ships to pin them down. Once the fleet is in the heat of battle, Scouts should move to a safe location since they lack combat capabilities.\r\n \r\n Lore\r\n These models are redesigned racing ships used in various circuits all over the solar system. They were commissioned for military use after high command had difficulty tracking the Bee fleet through usual means. \\\"Hacking and espionage are far less effective against enemies who speak neither English nor C#\\\" - Ned Feckland, Chief Intelligence Officer.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Striker\",\r\n \"Health\": 300,\r\n \"Range\": [0],\r\n \"Power\": [150],\r\n \"RateOfFire\": [0],\r\n \"RotationRates\": [0],\r\n \"Speed\": 18.75,\r\n \"Sight\": 40,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1],\r\n \"WeaponTypes\": [\"Bomb\"],\r\n \"Description\": \"Strikers are slower but sturdier than Drones, and they trade their standard weapons systems for explosives. They must get on top of their target to drop bombs, but deal high damage when successful. Can only be escorted into battles by a Carrier.\",\r\n \"CodexDescription\": \"Strikers are slower but sturdier than Drones, and they trade their standard weapons systems for explosives. They must get on top of their target to drop bombs, but deal high damage when successful. Can only be escorted into battles by a Carrier.\r\n \r\n Strategy\r\n Strikers have similar advantages to Drones, except that their bombs only strike once and strike hard. Should your Strikers survive a bombing run, send them back to your Carrier to receive new payloads.\r\n \r\n Lore\r\n Despite being similar to Drones in many ways, these ships are remotely piloted by humans as opposed to AI piloted. For the most part, this is better, except when Carrier crews take up all of the wifi bandwidth checking social media, causing lag for the remote pilots. (This is forbidden in Article 87, Subsection B of the Fleet Handbook and should be reported to superiors if witnessed.)\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Warp Gate\",\r\n \"Health\": 1350,\r\n \"Range\": [],\r\n \"Power\": [],\r\n \"RateOfFire\": [],\r\n \"RotationRates\": [],\r\n \"Speed\": 2,\r\n \"Sight\": 40,\r\n \"AdditionalTsv\": 45000,\r\n \"ProjectileValue\": [],\r\n \"WeaponTypes\": [],\r\n \"Description\": \"Slow, unmanned, heavily armored ship that allows other ships to retreat from the current level or call in limited reinforcements. If destroyed, the remaining ships must win or die. The Warp Gate cannot warp itself and will be lost any time a retreat is made.\",\r\n \"CodexDescription\": \"\"\r\n \r\n },\r\n \r\n \r\n \r\n {\r\n \"ShipType\": \"Beehive\",\r\n \"Health\": 2400,\r\n \"Range\": [],\r\n \"Power\": [],\r\n \"RateOfFire\": [],\r\n \"RotationRates\": [],\r\n \"Speed\": 2,\r\n \"Sight\": 40,\r\n \"AdditionalTsv\": 250000,\r\n \"ProjectileValue\": [],\r\n \"WeaponTypes\": [],\r\n \"Description\": \"The Beehive is less of a spacecraft and more of a structure. This imposing imitation of organic beehives exists as a safe haven for its fleet during battle. Other Bee ships can dock inside it to repair damages sustained during a fight.\",\r\n \"CodexDescription\": \"The Beehive is less of a spacecraft and more of a structure. This imposing imitation of organic beehives exists as a safe haven for its fleet during battle. Other Bee ships can dock inside it to repair damages sustained during a fight.\r\n \r\n Strategy\r\n Much like the Queen, a Beehive left unchecked will pose more problems the longer a battle goes on. Stay alert for these structures as well as any enemy ships that escape your sights after taking damage. If you can demolish a Beehive while it is hosting other ships, those ships will go down with it, which is a massive win. If you can\'t, though, you will be fighting the same ships multiple times in one battle.\r\n \r\n Lore\r\n Of all of the Bee fleet, this may be the most impressive piece of engineering. Being a moving port of sorts, it has the stability of a planet-side base and the mobility of a spacecraft.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Bumblebee\",\r\n \"Health\": 900,\r\n \"Range\": [160],\r\n \"Power\": [200],\r\n \"RateOfFire\": [2.75],\r\n \"RotationRates\": [180],\r\n \"Speed\": 7,\r\n \"Sight\": 0,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1.5],\r\n \"WeaponTypes\": [\"Turret\"],\r\n \"Description\": \"One of the most threatening ships the Bee fleet has shown. The only drawback we have ascertained of the Bumblebee is its average speed, but the pure firepower and staying power of this ship cannot be ignored, especially considering its exceptional range.\",\r\n \"CodexDescription\": \"One of the most threatening ships the Bee fleet has shown. The only drawback we have ascertained of the Bumblebee is its average speed, but the pure firepower and staying power of this ship cannot be ignored, especially considering its exceptional range.\r\n \r\n Strategy\r\n Bumblebee\'s have massive range, so the question you must answer when fighting it is how to circumvent that. To that end, there are two primary solutions. The first will be fast ships that can outmaneuver it while closing distance, although this requires expert piloting. The other is deploying ships with high durability, such as the Dreadnought or Barge, to absorb the damage while they escort your offensive ships. Beware, however, that you run a high risk of losing said durable ships in the process.\r\n \r\n Lore\r\n Our Gunship pilots seem to have their egos bruised by the superior kill count of the Bumblebees. Even more frustrating to them is that they have no way to tell if the Bumblebee pilots even care.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Carpenter Bee\",\r\n \"Health\": 600,\r\n \"Range\": [],\r\n \"Power\": [],\r\n \"RateOfFire\": [],\r\n \"RotationRates\": [],\r\n \"Speed\": 2,\r\n \"Sight\": 40,\r\n \"AdditionalTsv\": 15000,\r\n \"ProjectileValue\": [],\r\n \"WeaponTypes\": [],\r\n \"Description\": \"The resource gatherer for the Bees. This ship possesses no combat capabilities but is still uniquely valuable to their fleet, as the Factory ship is to ours.\",\r\n \"CodexDescription\": \"The resource gatherer for the Bees. This ship possesses no combat capabilities but is still uniquely valuable to their fleet, as the Factory ship is to ours.\r\n \r\n Strategy\r\n The Carpenter Bee has no weapons, and destroying them will limit the raw materials the Bees have to work with. It is still advised to prioritize more immediately threatening ships before the Carpenter Bee.\r\n \r\n Lore\r\nAllowing Carpenter Bees to mine contested areas will put our own Factory ships out of work. We have already received complaints, in fact, so we advise using the Factory ships when possible to avoid a miner\'s union strike.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Honeybee\",\r\n \"Health\": 40,\r\n \"Range\": [],\r\n \"Power\": [],\r\n \"RateOfFire\": [],\r\n \"RotationRates\": [],\r\n \"Speed\": 22.5,\r\n \"Sight\": 100,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [],\r\n \"WeaponTypes\": [],\r\n \"Description\": \"The Honeybee is built similarly to our Scouts. It is small, agile, and possesses no weaponry, so it presumably performs the same functions for the Bee fleet.\",\r\n \"CodexDescription\": \"The Honeybee is built similarly to our Scouts. It is small, agile, and possesses no weaponry, so it presumably performs the same functions for the Bee fleet.\r\n \r\n Strategy\r\n Just because the Honeybee lacks its own weapons does not mean it lacks power. If you can catch one, this will limit the enemy fleet\'s ability to anticipate our movements.\r\n \r\n Lore\r\n Fleet engineers are eager to gain access to an intact Honeybee in order to use its technology to modify their own personal vehicles. Please report this if it proves successful; this practice is specifically forbidden by the Fleet Handbook, as captured vessels are property of the United Fleet (Article 87, Subsection B).\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Hornet\",\r\n \"Health\": 100,\r\n \"Range\": [40],\r\n \"Power\": [20],\r\n \"RateOfFire\": [2],\r\n \"RotationRates\": [288],\r\n \"Speed\": 18,\r\n \"Sight\": 0,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1],\r\n \"WeaponTypes\": [\"Eye\"],\r\n \"Description\": \"Hornets travel in packs, using their numbers as their greatest advantage. These nimble ships are capable of swarming and overwhelming isolated enemies.\",\r\n \"CodexDescription\": \"Hornets travel in packs, using their numbers as their greatest advantage. These nimble ships are capable of swarming and overwhelming isolated enemies.\r\n \r\n Strategy\r\n Use ships like the Frigate and Cruiser that can damage multiple opposing spacecraft at once to efficiently deal with Hornet packs. If you notice a pack, don\'t allow your slower vessels to be swarmed.\r\n \r\n Lore\r\n The Hornets bear a striking resemblance to our own Drones, but they do not seem to need a Carrier to carry them into battle. Are they entirely independent spacecraft, or have we simply never seen their home ship?\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Leafcutter\",\r\n \"Health\": 600,\r\n \"Range\": [80],\r\n \"Power\": [60],\r\n \"RateOfFire\": [2], // This is tied to the animation (6 FPS) for the Leafcutter so it shouldn\'t be changed without very good reason\r\n \"RotationRates\": [250],\r\n \"Speed\": 10.5,\r\n \"Sight\": 0,\r\n \"AdditionalTsv\":0,\r\n \"ProjectileValue\": [1.5],\r\n \"WeaponTypes\": [\"Split Shot\"],\r\n \"Description\": \"This ship has been noted to have a similar build to our Dreadnoughts, but with more advanced offenses. Their ammunition is able to split into smaller pieces after impacting a target, like a shrapnel blast.\",\r\n \"CodexDescription\": \"This ship has been noted to have a similar build to our Dreadnoughts, but with more advanced offenses. Their ammunition is able to split into smaller pieces after impacting a target, like a shrapnel blast.\r\n \r\n Strategy\r\n The Leafcutter\'s shots are particularly potent fired into large groups of ships. Avoid engaging it with larger squads, particularly those made up of fragile or tightly grouped ships. Its low speed should make it reasonable to outmaneuver.\r\n \r\n Lore\r\n We have fielded requests from gunners assigned to Dreadnoughts asking for guns more like the Leafcutters. Gunship pilots have also specifically requested Dreadnoughts do not get this upgrade, as it would make them \\\"too cool.\\\" Either way, our engineers do not think it possible.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Queen\",\r\n \"Health\": 7000,\r\n \"Range\": [140, 70, 70, 70, 70],\r\n \"Power\": [180, 30, 30, 30, 30],\r\n \"RateOfFire\": [1.5, .5, .5, .5, .5],\r\n \"RotationRates\": [125, 250, 250, 250, 250],\r\n \"Speed\": 4,\r\n \"Sight\": 200,\r\n \"AdditionalTsv\": 3040, // the TSV for 16 Yellow Jackets (190)\r\n \"ProjectileValue\": [1, 1, 1, 1, 1],\r\n \"WeaponTypes\": [\"Eye\", \"Eye\", \"Eye\", \"Eye\", \"Eye\"],\r\n \"Description\": \"The largest and most threatening of the Bee Fleet. This ship is incredibly durable and can do some serious damage to your fleet if you aren\'t careful.\",\r\n \"CodexDescription\": \"The largest and most threatening of the Bee Fleet. This ship is incredibly durable and can do some serious damage to your fleet if you aren\'t careful.\r\n \r\n Strategy\r\n The Queen has many weapons on its large framework, so being within range is extremely dangerous. If you have access to Flagships, they can outrange the Queen, but otherwise you will need to get a powerful group of ships in range. Strikers are potent for a swift and critical blow, while high damage ships like Frigates and Cruisers are effective if escorted by more durable counterparts. Either way, do not ignore the Queen, as it produces its own Yellow Jackets. Over time it will become an unmanageable problem.\r\n \r\n Lore\r\n Fleet scientists theorize that this ship is too large for warping or high speed travels, and thus can only be built in our solar system. This provides a slight advantage, as an entire fleet of Queen Bees would have surely spelled doom for humanity. If the Bees get enough time and resources to construct more, however...\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Wasp\",\r\n \"Health\": 400,\r\n \"Range\": [40],\r\n \"Power\": [80],\r\n \"RateOfFire\": [2.5],\r\n \"RotationRates\": [240],\r\n \"Speed\": 15,\r\n \"Sight\": 0,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1],\r\n \"WeaponTypes\": [\"Eye\"],\r\n \"Description\": \"Wasps are extremely quick vessels with a surprising amount of armor. They are one of the more common members of the Bee fleet.\",\r\n \"CodexDescription\": \"Wasps are extremely quick vessels with a surprising amount of armor. They are one of the more common members of the Bee fleet.\r\n \r\n Strategy\r\n You will need ships that can either match the Wasp\'s speed or fire accurately enough when it does venture into their range. Thankfully, it doesn\'t hit as brutally as other enemies, so you don\'t need to go out of your way to destroy it. But outright ignoring any enemy vessel with weapons may still cause problems.\r\n \r\n Lore\r\n The running theory about Wasps is that they must be unmanned ships to contain the level of armor they do. Although that does raise the question of how many Bee ships can be unmanned, not to mention who is directing them.\"\r\n \r\n },\r\n {\r\n \"ShipType\": \"Yellow Jacket\",\r\n \"Health\": 200,\r\n \"Range\": [0],\r\n \"Power\": [200],\r\n \"RateOfFire\": [0],\r\n \"RotationRates\": [0],\r\n \"Speed\": 19.5,\r\n \"Sight\": 40,\r\n \"AdditionalTsv\": 0,\r\n \"ProjectileValue\": [1],\r\n \"WeaponTypes\": [\"Bomb\"],\r\n \"Description\": \"Yellow Jackets are packed with strong engines and stronger explosives, making a very dangerous foe. On the admittedly grim bright side, their payload can only be delivered once.\",\r\n \"CodexDescription\": \"Yellow Jackets are packed with strong engines and stronger explosives, making a very dangerous foe. On the admittedly grim bright side, their payload can only be delivered once.\r\n \r\n Strategy\r\nYellow Jackets are specifically designed to be suicide bombers, and they are extremely adept at the job. Do your best to take the frail vessel down before it can reach you, or you may suffer intense damages to your fleet. If necessary, play keepaway with your faster vessels in order to preserve your slower ships.\r\n \r\n Lore\r\n This kamikaze ship has an intentional design to it, leading us to believe that our enemy has either enough resources for remote controlled, one-time-use ships or enough fervor to sacrifice their own people. Both are terrifying possibilities.\"\r\n \r\n }\r\n ]', '2023-05-08 14:01:12', '2025-03-21 17:10:25'),
(12, 0, 6, 'starting-settings', '{\n \"HumanStartingShips\": [\n {\n \"Barge\": 100\n },\n {\n \"Carrier\": 100\n },\n {\n \"Cruiser\": 100\n },\n {\n \"Dreadnought\": 100\n },\n {\n \"Factory\": 100\n },\n {\n \"Fire Ship\": 100\n },\n {\n \"Flagship\": 100\n },\n {\n \"Frigate\": 100\n },\n {\n \"Gunship\": 300\n },\n {\n \"Scout\": 300\n },\n {\n \"Warp Gate\": 100\n }\n ],\n \"BeeStartingShips\": [\n {\n \"Beehive\": 100\n },\n {\n \"Bumblebee\": 100\n },\n {\n \"Carpenter Bee\": 100\n },\n {\n \"Honeybee\": 300\n },\n {\n \"Hornet\": 300\n },\n {\n \"Leafcutter\": 100\n },\n {\n \"Queen\": 100\n },\n {\n \"Wasp\": 300\n },\n {\n \"Yellow Jacket\": 500\n }\n ],\n \"HumanCampaignStartingShips\": [\n {\n \"Barge\": 5\n },\n {\n \"Carrier\": 3\n },\n {\n \"Cruiser\": 8\n },\n {\n \"Dreadnought\": 10\n },\n {\n \"Factory\": 0\n },\n {\n \"Fire Ship\": 3\n },\n {\n \"Flagship\": 1\n },\n {\n \"Frigate\": 15\n },\n {\n \"Gunship\": 15\n },\n {\n \"Scout\": 30\n },\n {\n \"Warp Gate\": 2\n }\n ],\n \"BeeCampaignStartingShips\": [\n {\n \"Beehive\": 10\n },\n {\n \"Bumblebee\": 10\n },\n {\n \"Carpenter Bee\": 10\n },\n {\n \"Honeybee\": 30\n },\n {\n \"Hornet\": 30\n },\n {\n \"Leafcutter\": 10\n },\n {\n \"Queen\": 10\n },\n {\n \"Wasp\": 30\n },\n {\n \"Yellow Jacket\": 50\n }\n ],\n \"SupplyCapacity\": [\n 10000000,\n 10000000\n ],\n \"DefaultShootingStrategy\": \"First Seen\"\n }', '2023-05-08 14:01:12', '2025-02-06 11:32:22'),
(13, 0, 6, 'configuration', '{\n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \"CensoredWords\": [\"fuck\", \"bitch\", \"shit\", \"fag\", \"ussy\", \"cunt\", \"rape\", \"rapist\", \"dick\", \"cock\", \"ass\", \"penis\", \"vagina\", \"tits\", \"porn\", \"naked\", \"sex\", \"damn\", \"douche\", \"twat\", \"nigga\", \"nigger\", \"negro\", \"black\", \"white\", \"red\", \"yellow\", \"asian\"],\n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \n \"IsDeadVersion\": false,\n \"UseLocalStorage\": false,\n \"MirrorStorage\": false,\n \n \"MaxSquadSize\": 10,\n \"MaxSquadWidth\": -1, // -1 Means match this to MaxSquadSize\n \"MaxSquadHeight\": 10,\n \"RotationMultiplier\": 16,\n \n \"HumanSide\": 2,\n \"BeeSide\": 1,\n \"DoesUserHaveController\": false,\n \"StorageChunkSize\": 2500000, //Ensure that the results aren\'t sent to the server until the end of the level\n \"StandardMaxTimeOnQueue\": 25, // seconds \n \"TimeScale\": 1,\n \n \"AISquadPatrolTime\": 60,\n \"AIPatrolMaxSize\": 100,\n \"AIRandomMovementMaxDistance\": 200,\n \"AISquadGuardTime\": -1, // -1 Means match this to AISquadPatrolTime\n \"AISquadFollowingTime\": -1, // -1 Means match this to AISquadPatrolTime\n \n \"CarrierCarryDroneMax\": 4,\n \"CarrierCarryStrikerMax\": 4,\n \"CarrierSquadCount\": 2, // half of the total squad count of a carrier, two drone squads, two striker squads\n \"ShootingStrategies\": [\"First Seen\", \"Random\", \"Revenge\", \"Most Dangerous\", \"Most Health\", \"Least Health\", \"Most Powerful\", \"Least Powerful\", \"Closest\", \"Furthest\",\n \"Most Range\", \"Least Range\", \"Fastest\",\n \"Slowest\", \"Most Valuable\", \"Least Valuable\", \"Type A\", \"Type B\", \"Type C\", \"Type D\", \"Type E\", \"Type F\", \"Type G\", \"Type H\", \"Type I\", \"Type J\", \"Type K\", \"Type L\",\n \"Type M\", \"Type N\", \"Type O\", \"Type P\", \"Type Q\", \"Type R\", \"Type S\", \"Type T\", \"Type U\", \"Type V, Type W\"], // 38\n \"Tooltips\": [\n {\"Box\": \"Make Box Formation\"},\n {\"Line\": \"Make Line Formation\"},\n {\"Arrow\": \"Make Arrow Formation\"},\n {\"Rectangle\": \"Make Rectangle Formation\"},\n {\"Pyramid\": \"Make Pyramid Formation\"},\n ],\n \n \n \"Yes\": \"Yes\",\n \"No\": \"No\",\n \"OK\": \"OK\",\n \"AreYouSure\": \"Are you sure?\",\n \"AreYouSureExit\": \"Are you sure you want to exit?\",\n \"LevelProgressLost\": \"All progress on the level will be lost\",\n \"DeleteSquadConfirmation\": \"This will permanently delete the squad. All stats will be erased and the ships will be returned to the fleet.\",\n \"ClearSquadConfirmation\": \"This will remove all unsaved changes to this squad.\",\n \"LoadSquadConfirmation\": \"There are unsaved squad changes. If you load a new squad, the unsaved changes to the current squad will be lost.\",\n \"ChooseSquadConfirmation\": \"This squad has unreplaced ships in it. It will enter the level below full strength.\",\n \"UnchooseSquadConfirmation\": \"This will remove the squad from the list of chosen squads. It will not participate in the level.\",\n \"GoBackConfirmation\": \"There are unsaved squad changes. If you go back to the main menu, the unsaved changes to the current squad will be lost.\",\n \"OverCapacityAlert\": \"We can only supply so many ships for this battle. Select squad(s) within your capacity limit.\",\n \"NoChosenSquadsAlert\": \"You must choose at least one squad to participate in the level.\",\n \"ChoosingUnsavedSquadAlert\": \"You must save or clear the changes to this squad before you can choose it for the level.\",\n \"ChoosingDeadSquadAlert\": \"All the ships in this squad are dead and there are no replacements left in the fleet.\",\n \"SquadSavingStatusAlert\": \"The squad is being saved (this takes longer than it should)...\",\n \"OverCapacityAlertTitle\": \"Your squad are over capacity!\",\n \"NoChosenSquadsAlertTitle\": \"No squads chosen!\",\n \"ChoosingUnsavedSquadAlertTitle\": \"Squad has unsaved changes!\",\n \"ChoosingDeadSquadAlertTitle\": \"This squad has no ships left!\",\n \"SquadSavingStatusAlertTitle\": \"Saving Squad...\",\n \n \n \"VisibleBeeShipTypes\": [\"Hornet\", \"Honeybee\", \"Bumblebee\", \"Leafcutter\", \"Queen\", \"Wasp\", \"Yellow Jacket\", \"Beehive\", \"Carpenter Bee\"],\n \"InvisibleBeeShipTypes\": [],\n \"VisibleHumanShipTypes\": [\"Carrier\", \"Cruiser\", \"Barge\", \"Dreadnought\", \"Flagship\", \"Frigate\", \"Gunship\", \"Fire Ship\", \"Scout\", \"Factory\", \"Warp Gate\"],\n \"InvisibleHumanShipTypes\": [],\n \"AISide\": \"BeeSide\",\n \"UserSide\": \"HumanSide\",\n \"SquadMakerFirstSide\": \"HumanSide\",\n \"SquadMakerSecondSide\": \"BeeSide\",\n \"TotalLevels\": 32,\n \"SquadGenerationCount\": 6\n \n }', '2023-05-08 14:01:12', '2025-02-28 10:43:47');
INSERT INTO `settings` (`Id`, `userId`, `version`, `name`, `contents`, `created_date`, `edited_date`) VALUES
(14, 0, 5, 'configuration', '{\n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                          \n                                                                    